// 1.0 «Explicación de cada respuesta incorrecta»: the book passage for each wrong option of the choice questions,
// generated by web/scripts/porque10.mjs into libro/porque/<parte>.json (see ESQUEMA.md, «Por qué no»). Read-only
// content: nothing is stored.

import { leerJSON } from '../../lib/datos';

/** The book's sentence that speaks to a wrong option, or «general» (the question's general explanation covers it). */
export type Porque = { k: 'libro'; html: string; ref: string; donde: string } | { k: 'general' };

export interface PorqueParte {
  version: 1;
  parte: string;
  /** Repaso question id → index of the option (in the question's `opciones`) → its explanation. */
  repaso: Record<string, Record<string, Porque>>;
  /** «<exercise label>/<question id>» → option index → explanation. */
  ejercicios: Record<string, Record<string, Porque>>;
  /** Prediction item id → «sube» | «baja» | «igual» → explanation. */
  prediccion: Record<string, Record<string, Porque>>;
}

const cache = new Map<string, Promise<PorqueParte | null>>();

/** The part's explanations (null when there are none or they could not be read: the general explanation stays). */
export function cargarPorque(parte: string): Promise<PorqueParte | null> {
  let p = cache.get(parte);
  if (!p) {
    p = leerJSON<PorqueParte>(`porque/${parte}.json`).catch(() => {
      cache.delete(parte);
      return null;
    });
    cache.set(parte, p);
  }
  return p;
}
